 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    colors = [c for c, n in counts.most_common() if c != bg]
    if not colors:
        return [row[:] for row in grid]
    marker = colors[0]
    seeds = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    # A marker color used inside a connected object is not a stamping signal.
    if any(any(0 <= rr < h and 0 <= cc < w and grid[rr][cc] not in (bg, marker)
               for rr, cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1))) for r,c in seeds):
        return [row[:] for row in grid]

    remaining = {(r,c) for r in range(h) for c in range(w)
                 if grid[r][c] != bg and grid[r][c] != marker}
    comps = []
    while remaining:
        start = remaining.pop()
        comp = {start}
        q = deque([start])
        while q:
            r,c = q.popleft()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in remaining:
                    remaining.remove(p); comp.add(p); q.append(p)
        comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    motif = max(comps, key=len)
    rmin=min(r for r,c in motif); rmax=max(r for r,c in motif)
    cmin=min(c for r,c in motif); cmax=max(c for r,c in motif)
    cr, cc=(rmin+rmax)//2, (cmin+cmax)//2
    stamp=[(r-cr,c-cc,grid[r][c]) for r,c in motif]
    out=[row[:] for row in grid]
    for r,c in seeds:
        for dr,dc,color in stamp:
            rr,cc2=r+dr,c+dc
            if 0 <= rr < h and 0 <= cc2 < w:
                out[rr][cc2]=color
    return out
